#include <unistd.h>
#include <string.h>
#include <stdio.h>
#include <errno.h>

int main() {
    const char *msg = "Writing data directly via write syscall.\n";
    size_t len = strlen(msg);
    ssize_t bytes_written;

    // Using STDOUT_FILENO (1) for standard output
    int fd = STDOUT_FILENO;

    // Attempt to write the message
    bytes_written = write(fd, msg, len);

    if (bytes_written == -1) {
        // Handle fatal error, checking errno
        perror("write failed");
        return 1;
    }

    if ((size_t)bytes_written < len) {
        // A partial write occurred. In production code, a loop would be required
        // to complete the transfer of the remaining bytes.
        fprintf(stderr, "Warning: Partial write occurred. Wrote %zd of %zu bytes.\n", 
                bytes_written, len);
    }

    return 0;
}
